import { create } from "@bufbuild/protobuf";
import { describe, expect, it } from "vitest";
import { formatViewCount } from "@/components/MemoDetailSidebar/MemoSharePanel";
import en from "@/locales/en.json";
import { MemoShareSchema } from "@/types/proto/api/v1/memo_service_pb";
import type { useTranslate } from "@/utils/i18n";

const t = ((key: string, options?: Record<string, unknown>) => {
  const template = key.split(".").reduce<unknown>((node, part) => (node as Record<string, unknown>)[part], en) as string;
  return template.replace(/\{\{(\w+)\}\}/g, (_m, name: string) => String(options?.[name]));
}) as ReturnType<typeof useTranslate>;

describe("formatViewCount", () => {
  it("shows count of limit when a limit is set — catches dropping the limit", () => {
    const share = create(MemoShareSchema, { viewCount: 3, viewLimit: 10 });
    expect(formatViewCount(share, t)).toBe("3 of 10 views");
  });

  it("shows only the count when no limit is set — catches printing a phantom limit", () => {
    const share = create(MemoShareSchema, { viewCount: 3 });
    expect(formatViewCount(share, t)).toBe("3 views");
  });
});
